### **6. 代码示例（核心部分）**
```javascript
// background.js
class SyncManager {
  constructor() {
    this.tokenManager = new TokenManager();
    this.syncQueue = new PriorityQueue(); // 按优先级排序
  }

  async syncData(data) {
    try {
      await this.tokenManager.refreshIfNeeded('primary_device');
      const response = await fetchSyncData(data);
      this.syncQueue.enqueue(response, Date.now() + 300000); // 5分钟后重试
    } catch (error) {
      this.syncQueue.enqueue({ error }, Date.now() + 10000); // 10秒后重试
    }
  }

  start() {
    chrome.alarms.create('syncCheck', { periodInMinutes: 5 });
    chrome.alarms.onAlarm.addListener(() => {
      this.syncQueue.process(); // 处理队列中的任务
    });
  }
}
```

