### **2.1 多层编码（7+种变换）**
#### **A. Base64 + XOR + ROT13 混合编码**
```c
#include <stdio.h>
#include <string.h>
#include <openssl/bio.h>
#include <openssl/evp.h>

unsigned char* base64_encode(unsigned char* data, int len) {
    BIO *bio, *b64, *mem;
    BUF_MEM *bufferPtr;
    b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_F_NO_FLUSH);
    mem = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, mem);
    BIO_write(bio, data, len);
    BIO_flush(b64);
    BIO_get_mem_ptr(mem, &bufferPtr);
    unsigned char* encoded = malloc(bufferPtr->length + 1);
    memcpy(encoded, bufferPtr->data, bufferPtr->length);
    BIO_free_all(bio);
    return encoded;
}

unsigned char* xor_encode(unsigned char* data, int len, unsigned char key) {
    unsigned char* encoded = malloc(len);
    for (int i = 0; i < len; i++) {
        encoded[i] = data[i] ^ key;
    }
    return encoded;
}

unsigned char* rot13_encode(unsigned char* data, int len) {
    unsigned char* encoded = malloc(len);
    for (int i = 0; i < len; i++) {
        if (data[i] >= 'A' && data[i] <= 'M') encoded[i] = data[i] + 13;
        else if (data[i] >= 'N' && data[i] <= 'Z') encoded[i] = data[i] - 13;
        else if (data[i] >= 'a' && data[i] <= 'm') encoded[i] = data[i] + 13;
        else if (data[i] >= 'n' && data[i] <= 'z') encoded[i] = data[i] - 13;
        else encoded[i] = data[i];
    }
    return encoded;
}
```

