import subprocess
import os

def generate_obfuscated_shellcode(original_shellcode_path, output_path):
    # 1. Base64编码
    base64_cmd = f"echo -n $(cat {original_shellcode_path} | base64) > base64.bin"
    subprocess.run(base64_cmd, shell=True)

    # 2. XOR编码（key=0x42）
    xor_cmd = f"xxd -p -c 1 base64.bin | awk '{{printf "%c", $1 ^ 66}}' > xor.bin"
    subprocess.run(xor_cmd, shell=True)

    # 3. 指令重排（C程序）
    c_shuffle = """
    #include <stdio.h>
    #include <stdlib.h>
    unsigned char shellcode[] = {0x42, 0x41, 0x43, ...}; // 实际Shellcode
    void shuffle() { ... }
    int main() { shuffle(); return 0; }
    """
    with open("shuffle.c", "w") as f:
        f.write(c_shuffle)
    subprocess.run("gcc shuffle.c -o shuffle", shell=True)
