### **2. 智能合约实现**
#### **核心合约：`DecentralizedC2Command.sol`**
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract DecentralizedC2Command is ERC721, Ownable {
    struct Command {
        address sender;
        address receiver;
        uint256 timestamp;
        bytes32 commandHash; // Keccak256(commandData)
        bool executed;
        string status; // "PENDING", "EXECUTED", "REVOKED"
    }

    mapping(uint256 => Command) public commands;
    mapping(address => bool) public isOperator;

    event CommandCreated(uint256 id, address sender, address receiver, bytes32 commandHash);
    event CommandExecuted(uint256 id, address executor);
    event CommandRevoked(uint256 id, address revoker);

    constructor() ERC721("DecentralizedC2Command", "DCC") {}

    // 仅Admin或Operator可创建指令
    function createCommand(
        address receiver,
        bytes memory commandData,
        bytes memory signature
    ) external {
        require(isOperator(msg.sender) || msg.sender == owner(), "No permission");
        bytes32 commandHash = keccak256(commandData);
        uint256 id = _tokenIdCounter++;

        _safeMint(msg.sender, id);
        commands[id] = Command({
            sender: msg.sender,
            receiver: receiver,
            timestamp: block.timestamp,
            commandHash: commandHash,
            executed: false,
            status: "PENDING"
        });

        emit CommandCreated(id, msg.sender, receiver, commandHash);
    }

    // 接收者执行指令（需签名验证）
    function executeCommand(
        uint256 id,
        bytes memory signature
    ) external {
        Command storage cmd = commands[id];
        require(cmd.receiver == msg.sender, "Not the receiver");
        require(cmd.status == "PENDING", "Command already executed");

        // 验证签名（简化示例，实际需使用ECDSA.verify）
        require(verifySignature(msg.sender, cmd.commandHash, signature), "Invalid signature");

        cmd.executed = true;
        cmd.status = "EXECUTED";
        emit CommandExecuted(id, msg.sender);
    }

    // Admin撤销指令
    function revokeCommand(uint256 id) external onlyOwner {
        Command storage cmd = commands[id];
        require(cmd.status == "PENDING", "Command already executed");
        cmd.status = "REVOKED";
        emit CommandRevoked(id, msg.sender);
    }

    // 仅Admin可添加Operator
    function addOperator(address operator) external onlyOwner {
        isOperator[operator] = true;
    }
}
```

#### **关键功能扩展**
1. **指令哈希化**：所有指令内容（如JSON数据）先哈希后存储，避免重复计算。
2. **离链存储**：指令详情（如完整JSON）存储于**IPFS/Arweave**，仅哈希值存链。
3. **跨链支持**：通过**Wrapped NFT**或**Layer 2**实现跨链指令同步（如Polygon的ERC-721兼容性）。
4. **权限升级**：使用**ERC-1155**管理动态权限（如"读权限"、"写权限"）。

